-- ============================================================================
-- PNC OVERALL SUMMARY (women) - complete / missing mandatory and conditional fields
-- INPUT: a table or CTE named `mahis_pivot` (output of pnc/mahis_pnc_pivot.sql). To use a CTE instead of a table, put this script's
-- WITH list after `WITH RECURSIVE mahis_pivot AS ( <pivot query> ),`
-- Generated by build_dqa_scripts.py from the MNH Neonatal data dictionary rules.
-- ============================================================================
SET SESSION group_concat_max_len = 1000000;

WITH woman_level AS (
    -- One row per woman: latest non-empty value of each field across all visit days
    SELECT
        p.person_id,
        SUBSTRING_INDEX(GROUP_CONCAT(p.location_id ORDER BY p.visit_date DESC), ',', 1) AS location_id,
        MIN(p.visit_date) AS first_visit_date,
        MAX(p.visit_date) AS last_visit_date,
        COUNT(DISTINCT p.visit_date) AS number_of_visits,
        DATEDIFF(MAX(p.visit_date), MIN(p.visit_date)) + 1 AS days_spanned,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.sexually_transmitted_infection AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS sexually_transmitted_infection,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.dehydration AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS dehydration,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.umbilical_hernia AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS umbilical_hernia,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.ankyloglossia AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS ankyloglossia,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.coma AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS coma,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.cyanosis AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS cyanosis,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.pallor AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS pallor,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.vaccines AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS vaccines,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.convulsion AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS convulsion,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.parity AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS parity,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.other_neck_abnormality_notes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS other_neck_abnormality_notes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.wheezes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS wheezes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.danger_signs AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS danger_signs,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.time_of_referral AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS time_of_referral,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.apgar_score_at_5_minutes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS apgar_score_at_5_minutes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.circumference AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS circumference,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mode_of_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mode_of_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.outcome_of_the_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS outcome_of_the_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.past_pregnancy_problems AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS past_pregnancy_problems,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.other_danger_signs_notes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS other_danger_signs_notes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.intervention_given AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS intervention_given,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.status_of_lochia AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS status_of_lochia,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.episiotomy_tear AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS episiotomy_tear,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.condition_of_episiotomy_tear AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS condition_of_episiotomy_tear,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.current_weight AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS current_weight,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.date_bcg_given AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS date_bcg_given,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.date_polio_given AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS date_polio_given,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.chest_in_drawing AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS chest_in_drawing,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.intervention_notes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS intervention_notes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.cotrimoxazole_prophylaxis AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS cotrimoxazole_prophylaxis,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.status_of_the_mother AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS status_of_the_mother,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.postnatal_check_period AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS postnatal_check_period,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.vitamin_a_supplementation AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS vitamin_a_supplementation,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.counselling_on_family_planning AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS counselling_on_family_planning,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.postnatal_visit_period AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS postnatal_visit_period,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.intervention_on_danger_signs AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS intervention_on_danger_signs,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.discharge_status_of_woman AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS discharge_status_of_woman,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdominal_distention AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdominal_distention,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.protected_at_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS protected_at_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.how_many_doses_of_tdv_did_the_mother_receive AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS how_many_doses_of_tdv_did_the_mother_receive,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.positioning AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS positioning,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.referral_facility AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS referral_facility,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.grunting AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS grunting,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.spinal_bifida AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS spinal_bifida,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reflexes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reflexes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.femoral_pulses AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS femoral_pulses,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.extra_digits AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS extra_digits,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.talipes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS talipes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.moro_reflex AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS moro_reflex,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.health_education AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS health_education,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mother_vdrl_syphilis_result AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mother_vdrl_syphilis_result,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mother_hepatitis_result AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mother_hepatitis_result,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.cleftlippalate AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS cleftlippalate,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.crackles AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS crackles,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.hiv_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS hiv_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.systolic_blood_pressure AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS systolic_blood_pressure,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.diastolic_blood_pressure AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS diastolic_blood_pressure,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.pulse AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS pulse,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.temperature_c AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS temperature_c,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.weight_kg AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS weight_kg,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.height AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS height,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.sao2 AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS sao2,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.appointment_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS appointment_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.respiratory_rate AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS respiratory_rate,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.head_circumference AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS head_circumference,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.date_of_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS date_of_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.birth_weight AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS birth_weight,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.nasal_flaring AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS nasal_flaring,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_babies AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_babies,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.time_of_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS time_of_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.cord_prolapse AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS cord_prolapse,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mother_hiv_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mother_hiv_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.breast_feeding AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS breast_feeding,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reason_for_referral AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reason_for_referral,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.status_of_uterus AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS status_of_uterus,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.place_of_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS place_of_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.status_of_baby AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS status_of_baby,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.airway AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS airway,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.breathing AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS breathing,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.circulation AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS circulation,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.other_sti AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS other_sti,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.newborn_baby_complications AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS newborn_baby_complications,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.staff_conducting_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS staff_conducting_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.visit_date_56833 AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS visit_date_56833,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.blood_pressure AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS blood_pressure,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.patient_enrolled AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS patient_enrolled,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.lumps AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS lumps,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.birth_injuries AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS birth_injuries,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.past_stis AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS past_stis,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.syphilis_serologically_diagnosed AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS syphilis_serologically_diagnosed,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.babinski AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS babinski,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.capillary_refill_less_than_3_seconds AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS capillary_refill_less_than_3_seconds,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.coldness AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS coldness,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.degree_of_perineal_tear AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS degree_of_perineal_tear,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.degree_of_tear AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS degree_of_tear,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.descended_testicles AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS descended_testicles,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.ear_discharges AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS ear_discharges,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.false_teeth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS false_teeth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.fontanelles AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS fontanelles,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.grasping AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS grasping,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.missing_digits AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS missing_digits,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.murmurs AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS murmurs,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.nose_deformities AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS nose_deformities,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.nose_discharges AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS nose_discharges,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.nose_shape AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS nose_shape,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.patent_anus AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS patent_anus,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.rooting AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS rooting,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.short_neck AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS short_neck,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.stepping AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS stepping,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.webbing AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS webbing,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.weight_grams AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS weight_grams,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.art_regimen AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS art_regimen,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.condition_on_referral AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS condition_on_referral,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.fetal_conditions AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS fetal_conditions,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.maternal_conditions AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS maternal_conditions,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.past_modes_of_delivery_other_specify AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS past_modes_of_delivery_other_specify,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.placenta_conditions AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS placenta_conditions,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.specify_other_facility AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS specify_other_facility,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.type_of_immunization_the_baby_received AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS type_of_immunization_the_baby_received,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.ambiguous_genitalia AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS ambiguous_genitalia,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdomen_abdominal_wall_defects AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdomen_abdominal_wall_defects,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdomen_bleeding_from_cord AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdomen_bleeding_from_cord,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdomen_organomegaly AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdomen_organomegaly,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdomen_umbilicus_red AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdomen_umbilicus_red,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.attachment AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS attachment,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.audible_suck AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS audible_suck,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_hiv_positive AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_hiv_positive,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.did_the_baby_cry_at_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS did_the_baby_cry_at_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.fetal_other_specify AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS fetal_other_specify,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.gbv AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS gbv,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mental_health_concerns_at_visit AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mental_health_concerns_at_visit,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mother_has_concerns_about_feeding AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mother_has_concerns_about_feeding,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.nipple_shape AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS nipple_shape,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.placenta_other_specify AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS placenta_other_specify,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.postpartum_family_planning_method_after_6_weeks_breastf AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS postpartum_family_planning_method_after_6_weeks_breastf,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.eyes_jaundice AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS eyes_jaundice,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.eyes_presence_of_the_eye_ball AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS eyes_presence_of_the_eye_ball,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.ear_shape AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS ear_shape,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.ear_level AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS ear_level,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.ear_blockage AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS ear_blockage,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.sucking_reflex AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS sucking_reflex,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdomen_pus_from_cord AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdomen_pus_from_cord,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdomen_cord_dry AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdomen_cord_dry,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdomen_foul_smelling_cord AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdomen_foul_smelling_cord,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.required_orifices_present AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS required_orifices_present,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.female_discharges AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS female_discharges,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.erb_s_palsy_bronchial_nerve_injury AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS erb_s_palsy_bronchial_nerve_injury,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.has_the_woman_been_initiated_on_art_treatment AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS has_the_woman_been_initiated_on_art_treatment,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.ear_symmetry AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS ear_symmetry,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.eyes_discharges AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS eyes_discharges,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.health_education_topics AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS health_education_topics,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.itn_provided AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS itn_provided,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_vaccines_given AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_vaccines_given,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdomen_granuloma AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdomen_granuloma,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.gender AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS gender,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.birthdate AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS birthdate,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.birthdate_estimated AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS birthdate_estimated,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.first_pnc_visit AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS first_pnc_visit,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.age_years_at_first_pnc_visit AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS age_years_at_first_pnc_visit,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.record_type AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS record_type,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.related_person_ids AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS related_person_ids,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.related_relationships AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS related_relationships,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.dead AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS dead,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.death_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS death_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.arv_number_identifier AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS arv_number_identifier,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_ward_mother_rounds AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_ward_mother_rounds,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_ward_baby_rounds AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_ward_baby_rounds,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.other_programs_hiv_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS other_programs_hiv_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.other_programs_art_number AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS other_programs_art_number,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.other_programs_facility_for_art AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS other_programs_facility_for_art
    FROM mahis_pivot p
    WHERE p.record_type = 'woman'
    GROUP BY p.person_id
),

rules AS (
    SELECT 'mother_hiv_status' AS rule_id, 'pnc_hiv_mother_hiv_status' AS dictionary_name, 'HIV status of woman' AS label, 'HIV' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'has_the_woman_been_initiated_on_art_treatment' AS rule_id, 'pnc_hiv_started_art_treatment' AS dictionary_name, 'Has the woman started ART treatment?' AS label, 'HIV' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'art_clinic_number' AS rule_id, 'pnc_hiv_art_clinic_registration_number' AS dictionary_name, 'ART clinic number' AS label, 'HIV' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'time_of_referral' AS rule_id, 'pnc_disch_time_referral / pnc_ref_time_referral / pnc_end_time_referral' AS dictionary_name, 'Time of referral' AS label, 'Referral / Discharge' AS section, 'CONDITIONAL' AS requirement, 'Woman was referred (any referral detail recorded)' AS condition_text
    UNION ALL
    SELECT 'reason_for_referral' AS rule_id, 'pnc_disch_reason_referral / pnc_end_reason_referral' AS dictionary_name, 'Reason for referral (free text)' AS label, 'Referral / Discharge' AS section, 'CONDITIONAL' AS requirement, 'Woman was referred (any referral detail recorded)' AS condition_text
    UNION ALL
    SELECT 'condition_on_referral' AS rule_id, 'pnc_disch_condition_referral / pnc_end_condition_referral' AS dictionary_name, 'Woman''s condition on referral' AS label, 'Referral / Discharge' AS section, 'CONDITIONAL' AS requirement, 'Woman was referred (any referral detail recorded)' AS condition_text
    UNION ALL
    SELECT 'other_programs_facility_for_art' AS rule_id, 'pnc_disch_facility_art / pnc_end_facility_art' AS dictionary_name, 'Facility for ART' AS label, 'HIV' AS section, 'CONDITIONAL' AS requirement, 'Woman has started ART (my interpretation: the dictionary gives no relevance rule)' AS condition_text
    UNION ALL
    SELECT 'death_date' AS rule_id, 'pnc_end_date_death' AS dictionary_name, 'Date of death' AS label, 'Death' AS section, 'CONDITIONAL' AS requirement, 'Woman recorded as dead' AS condition_text
),

woman_rule_results AS (
    -- woman_level is read once: every rule result is packed as [applicable, present] in one JSON object per woman
    SELECT person_id, JSON_OBJECT(
        'mother_hiv_status', JSON_ARRAY(1, CASE WHEN (COALESCE(mother_hiv_status, other_programs_hiv_status)) IS NOT NULL THEN 1 ELSE 0 END),
        'has_the_woman_been_initiated_on_art_treatment', JSON_ARRAY(1, CASE WHEN (has_the_woman_been_initiated_on_art_treatment) IS NOT NULL THEN 1 ELSE 0 END),
        'art_clinic_number', JSON_ARRAY(1, CASE WHEN (COALESCE(other_programs_art_number, arv_number_identifier)) IS NOT NULL THEN 1 ELSE 0 END),
        'time_of_referral', JSON_ARRAY(CASE WHEN COALESCE(((reason_for_referral IS NOT NULL OR referral_facility IS NOT NULL OR time_of_referral IS NOT NULL OR condition_on_referral IS NOT NULL OR LOWER(discharge_status_of_woman) LIKE '%refer%')), 0) THEN 1 ELSE 0 END, CASE WHEN (time_of_referral) IS NOT NULL THEN 1 ELSE 0 END),
        'reason_for_referral', JSON_ARRAY(CASE WHEN COALESCE(((reason_for_referral IS NOT NULL OR referral_facility IS NOT NULL OR time_of_referral IS NOT NULL OR condition_on_referral IS NOT NULL OR LOWER(discharge_status_of_woman) LIKE '%refer%')), 0) THEN 1 ELSE 0 END, CASE WHEN (reason_for_referral) IS NOT NULL THEN 1 ELSE 0 END),
        'condition_on_referral', JSON_ARRAY(CASE WHEN COALESCE(((reason_for_referral IS NOT NULL OR referral_facility IS NOT NULL OR time_of_referral IS NOT NULL OR condition_on_referral IS NOT NULL OR LOWER(discharge_status_of_woman) LIKE '%refer%')), 0) THEN 1 ELSE 0 END, CASE WHEN (condition_on_referral) IS NOT NULL THEN 1 ELSE 0 END),
        'other_programs_facility_for_art', JSON_ARRAY(CASE WHEN COALESCE((LOWER(has_the_woman_been_initiated_on_art_treatment) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (other_programs_facility_for_art) IS NOT NULL THEN 1 ELSE 0 END),
        'death_date', JSON_ARRAY(CASE WHEN COALESCE((dead = '1'), 0) THEN 1 ELSE 0 END, CASE WHEN (death_date) IS NOT NULL THEN 1 ELSE 0 END)
    ) AS j
    FROM woman_level
),

field_status AS (
    -- Unpivot the JSON into one row per woman per rule
    SELECT
        b.person_id,
        k.rule_id,
        r.requirement,
        CAST(JSON_EXTRACT(b.j, CONCAT('$.', k.rule_id, '[0]')) AS UNSIGNED) AS applicable,
        CAST(JSON_EXTRACT(b.j, CONCAT('$.', k.rule_id, '[1]')) AS UNSIGNED) AS present
    FROM woman_rule_results b
    JOIN JSON_TABLE(JSON_KEYS(b.j), '$[*]' COLUMNS (rule_id VARCHAR(100) PATH '$')) k
    INNER JOIN rules r ON r.rule_id = k.rule_id
),

woman_dq AS (
    -- Per-woman counts of mandatory and conditional fields
    SELECT
        b.person_id,
        SUM(CASE WHEN f.requirement = 'MANDATORY' THEN 1 ELSE 0 END) AS mandatory_fields,
        SUM(CASE WHEN f.requirement = 'MANDATORY' AND f.present = 1 THEN 1 ELSE 0 END) AS mandatory_present,
        SUM(CASE WHEN f.requirement = 'MANDATORY' AND f.present = 0 THEN 1 ELSE 0 END) AS mandatory_missing,
        SUM(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 THEN 1 ELSE 0 END) AS conditional_required,
        SUM(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 AND f.present = 1 THEN 1 ELSE 0 END) AS conditional_present,
        SUM(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 AND f.present = 0 THEN 1 ELSE 0 END) AS conditional_missing,
        GROUP_CONCAT(CASE WHEN f.requirement = 'MANDATORY' AND f.present = 0 THEN f.rule_id END ORDER BY f.rule_id SEPARATOR '; ') AS missing_mandatory_fields,
        GROUP_CONCAT(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 AND f.present = 0 THEN f.rule_id END ORDER BY f.rule_id SEPARATOR '; ') AS missing_conditional_fields
    FROM woman_level b
    INNER JOIN field_status f ON f.person_id = b.person_id
    GROUP BY b.person_id
)

SELECT 'Total women' AS measure, COUNT(*) AS women, 100.0 AS pct FROM woman_dq
UNION ALL SELECT 'Women with ALL mandatory fields present', SUM(mandatory_missing = 0), ROUND(100 * SUM(mandatory_missing = 0) / COUNT(*), 1) FROM woman_dq
UNION ALL SELECT 'Women with MISSING mandatory fields', SUM(mandatory_missing > 0), ROUND(100 * SUM(mandatory_missing > 0) / COUNT(*), 1) FROM woman_dq
UNION ALL SELECT 'Women with required conditional fields missing', SUM(conditional_missing > 0), ROUND(100 * SUM(conditional_missing > 0) / COUNT(*), 1) FROM woman_dq
UNION ALL SELECT 'Women with all mandatory AND all required conditional fields present', SUM(mandatory_missing = 0 AND conditional_missing = 0), ROUND(100 * SUM(mandatory_missing = 0 AND conditional_missing = 0) / COUNT(*), 1) FROM woman_dq
UNION ALL SELECT 'Women with required conditional fields (any triggered)', SUM(conditional_required > 0), ROUND(100 * SUM(conditional_required > 0) / COUNT(*), 1) FROM woman_dq
UNION ALL SELECT 'Average mandatory completeness (% of mandatory fields present per woman)', COUNT(*), ROUND(AVG(100 * mandatory_present / mandatory_fields), 1) FROM woman_dq
UNION ALL SELECT 'Average required-conditional completeness (% present per woman)', SUM(conditional_required > 0), ROUND(AVG(CASE WHEN conditional_required > 0 THEN 100 * conditional_present / conditional_required END), 1) FROM woman_dq;
